<?php session_start();if(!isset($_SESSION['user_id'])){header('Location:login.php');exit;}require_once '../config/database.php';$uid=$_SESSION['user_id'];if($_SERVER['REQUEST_METHOD']==='POST'){$no='SB-'.date('YmdHis').'-'.random_int(100,999);$q=$pdo->prepare('INSERT INTO tickets(ticket_no,user_id,subject,category,priority) VALUES(?,?,?,?,?)');$q->execute([$no,$uid,trim($_POST['subject']),$_POST['category'],$_POST['priority']]);$id=$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO ticket_messages(ticket_id,sender_id,message) VALUES(?,?,?)');$q->execute([$id,$uid,trim($_POST['message'])]);header('Location:chat.php?id='.$id);exit;}$q=$pdo->prepare('SELECT * FROM tickets WHERE user_id=? ORDER BY updated_at DESC');$q->execute([$uid]);$ts=$q->fetchAll();?><!doctype html><html><body style="font-family:Arial;background:#f4f7fb"><div style="background:#111827;color:white;padding:18px">☀️ SB SOLAR ENERGY <a href="logout.php" style="float:right;color:white">Logout</a></div><main style="max-width:1100px;margin:auto;padding:25px"><h2>My Tickets</h2><?php foreach($ts as $t):?><div style="background:white;padding:18px;margin:10px 0;border-radius:10px"><b><?=htmlspecialchars($t['ticket_no'])?></b> — <?=htmlspecialchars($t['subject'])?><p><?=htmlspecialchars($t['priority'])?> · <?=htmlspecialchars($t['status'])?></p><a href="chat.php?id=<?=$t['id']?>">Open Chat</a></div><?php endforeach;?><hr><h2>Create Ticket</h2><form method="post" style="background:white;padding:20px;border-radius:10px"><input name="subject" placeholder="Subject" required style="width:100%;padding:10px"><br><br><select name="category"><option>Solar Installation</option><option>Service / Complaint</option><option>Quotation</option><option>Payment</option><option>General</option></select><select name="priority"><option>Low</option><option selected>Medium</option><option>High</option><option>Urgent</option></select><br><br><textarea name="message" rows="6" placeholder="Describe your issue" required style="width:100%"></textarea><br><button>Create Ticket</button></form></main></body></html>